/**
 * Import Book II Art  -  bring-your-own-book macro for the Stonetop system.
 *
 * Regenerates the copyrighted Book II illustrations for monsters and locations
 * from a PDF you own, and wires them into the Monsters + Stonetop compendia.
 * Ships NO copyrighted pixels: this macro contains only page numbers, the pixel
 * dimensions + placement of each illustration, and document ids. You supply the book.
 *
 * How it works (faithful to the original private-project pipeline):
 *   The Book II illustrations are 1-bit ink stencils (PDF image masks). This macro
 *   walks each page's operator list, finds the image whose native size + placement
 *   match the manifest, and pulls the raw stencil straight out of pdf.js - so the
 *   body text laid OVER a full-bleed illustration is never included. No cropping,
 *   no text bleed; exactly the clean illustration the book embeds.
 *
 * How to use:
 *   1. Run as a GM (or a user with the "Upload New Files" permission).
 *   2. Pick your Book II PDF when prompted (the 302-page "spreads" edition).
 *   3. Optionally supply the five poster maps (Stonetop village, the Vicinity,
 *      the World's End, Marshedge, Gordin's Delve) as image files you own; each
 *      one becomes a ready-to-use navigation Scene, and the village map gets its
 *      lettered places-of-interest pins placed automatically.
 *   4. Wait ~1-2 min. It reads ~102 pages, extracts 134 images, writes WebPs, and
 *      updates 60 monster actors + 90 journal pages. The art is embedded into BOTH the
 *      compendia AND the world copies already in your sidebar (actors + the seeded
 *      gazetteer / bestiary journals), so you see it wherever you actually read.
 *
 * Re-runnable and idempotent. Images are written to a DURABLE folder OUTSIDE the
 * system (CONFIG.ROOT, default "stonetop-book-art"), so a Stonetop update or reinstall
 * never wipes them, and the system re-applies the art to the compendia automatically
 * on each update. You normally run this ONCE; re-run only to import from a new PDF or
 * to pick up art added in a later system version. Images already on disk are skipped
 * (SKIP_EXISTING), so a re-run after a manifest upgrade only extracts the new entries;
 * use FORCE to re-extract deliberately.
 */

const CONFIG = {
  // Durable asset + img-src root, OUTSIDE the system folder so a Stonetop update or
  // reinstall never wipes the extracted art. Reads the world setting the system
  // registers; falls back to the default folder if it isn't registered (older world).
  ROOT: (game.settings.settings?.has?.("stonetop_pwd.book2ArtRoot")
    ? game.settings.get("stonetop_pwd", "book2ArtRoot") : "") || "stonetop-book-art",
  QUALITY: 0.85,                  // WebP quality (matches the original apply step)
  MAXDIM: 1600,                   // cap on the long side; never upscales past native
  RELOCK_PACKS: true,            // restore pack lock state when done
  SYNC_WORLD_ACTORS: true,       // also update world actors imported from the Monsters pack
  SYNC_WORLD_JOURNALS: true,     // also embed art into world journals seeded from the Stonetop pack
                                 // (the gazetteer + bestiary codex in your sidebar), not just the compendium
  UPDATE_TOKEN_ART: true,        // also point each actor's prototype token at the new illustration
  TOKEN_FIT: "cover",            // how the token image fills its square: "cover" (fill, crop the wide
                                 // sides), "contain" (whole illustration, letterboxed), "fill", "width", "height"
  DRY_RUN: false,                // true = extract + report, write nothing
  STRICT_PAGES: false,           // true = abort if the PDF page count is unexpected
  IMPORT_MAPS: true,             // offer the optional poster-map -> Scene step
  MAP_MAXDIM: 6000,              // cap on a supplied map's long side; never upscales
  PAGEMAP_MAXDIM: 2000,          // cap on a rasterised page region ("pagemap" rows). Separate from
                                 // MAXDIM because these are rendered, not lifted: the printed maps
                                 // carry their location labels as text drawn over a ~700px raster,
                                 // so they are rendered well above target (PAGEMAP_DPI) and
                                 // downsampled ONCE to here, which keeps the labels legible.
  PAGEMAP_DPI: 300,              // fallback render resolution for a pagemap row without its own `dpi`
  SKIP_EXISTING: true,           // upgrade path: don't re-extract images already on disk,
                                 // so a manifest with new entries only processes the delta
  FORCE: false,                  // true = re-extract everything even if present;
                                 // or a list of out-path substrings, e.g. ["crinwin", "the-flats-2"].
                                 // The intro dialog's "Force update" checkbox forces this to true for a run.
  OP_TIMEOUT_MS: 60000,          // per-image/per-page watchdog. A pdf.js object callback that never
                                 // fires (page.objs.get) or a stalled file upload resolves no promise
                                 // and throws no error, so the import sticks at "N/total" forever with
                                 // a clean console. Race every such await against this so one stuck
                                 // image fails and is logged like any other, and the loop moves on.
};

